//! Small scanning helpers shared by the highlighters.

#[inline]
pub fn is_word(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

#[inline]
pub fn is_digit(b: u8) -> bool {
    b.is_ascii_digit()
}

#[inline]
pub fn is_hex(b: u8) -> bool {
    b.is_ascii_hexdigit()
}

#[inline]
pub fn is_ws(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// ASCII word boundary at byte offset `i` of `s`.
#[inline]
pub fn at_boundary(s: &[u8], i: usize) -> bool {
    let before = if i == 0 { false } else { is_word(s[i - 1]) };
    let after = if i >= s.len() { false } else { is_word(s[i]) };
    before != after
}

/// True when position `i` starts a token, i.e. the byte before it is not a word char.
#[inline]
pub fn left_free(s: &[u8], i: usize) -> bool {
    i == 0 || !is_word(s[i - 1])
}

/// True when position `i` ends a token, i.e. the byte at `i` is not a word char.
#[inline]
pub fn right_free(s: &[u8], i: usize) -> bool {
    i >= s.len() || !is_word(s[i])
}

/// Length of the run of digits starting at `i` (possibly zero).
#[inline]
pub fn digit_run(s: &[u8], i: usize) -> usize {
    let mut j = i;
    while j < s.len() && is_digit(s[j]) {
        j += 1;
    }
    j - i
}

