use crate::engine::Highlighter;
use crate::scan::*;
use crate::style::Paint;

/// `\b\d+(\.\d+)?\b`
pub struct Numbers {
    pub number: Paint,
}

impl Highlighter for Numbers {
    fn apply(&self, input: &str, out: &mut String) {
        let s = input.as_bytes();
        let mut i = 0usize;
        let mut last = 0usize;
        while i < s.len() {
            if !is_digit(s[i]) || !left_free(s, i) {
                i += 1;
                continue;
            }
            let mut j = i + digit_run(s, i);
            // optional fractional part, abandoned when it breaks the right boundary
            if j + 1 < s.len() && s[j] == b'.' && is_digit(s[j + 1]) {
                let k = j + 1 + digit_run(s, j + 1);
                if right_free(s, k) {
                    j = k;
                }
            }
            if !right_free(s, j) {
                i += 1;
                continue;
            }
            out.push_str(&input[last..i]);
            self.number.wrap(&input[i..j], out);
            i = j;
            last = j;
        }
        out.push_str(&input[last..]);
    }
}

/// `\b0[xX](HEX{16}|HEX{8})\b`
pub struct Pointers {
    pub number: Paint,
    pub letter: Paint,
    pub separator: Paint,
    pub bullet: Paint,
}

impl Pointers {
    fn hex(&self, c: u8, out: &mut String) {
        if c.is_ascii_digit() {
            self.number.wrap_char(c as char, out);
        } else {
            self.letter.wrap_char(c as char, out);
        }
    }
}

impl Highlighter for Pointers {
    fn apply(&self, input: &str, out: &mut String) {
        let s = input.as_bytes();
        let mut i = 0usize;
        let mut last = 0usize;
        while i < s.len() {
            if s[i] != b'0' || !left_free(s, i) || i + 1 >= s.len() {
                i += 1;
                continue;
            }
            if s[i + 1] != b'x' && s[i + 1] != b'X' {
                i += 1;
                continue;
            }
            let start = i + 2;
            let mut n = 0usize;
            while start + n < s.len() && is_hex(s[start + n]) {
                n += 1;
            }
            let digits = if n >= 16 && right_free(s, start + 16) {
                16
            } else if n >= 8 && right_free(s, start + 8) {
                8
            } else {
                i += 1;
                continue;
            };
            out.push_str(&input[last..i]);
            self.number.wrap_char('0', out);
            self.separator.wrap_char(s[i + 1] as char, out);
            for (k, &c) in s[start..start + digits].iter().enumerate() {
                if digits == 16 && k == 8 {
                    self.bullet.wrap_char('\u{2022}', out);
                }
                self.hex(c, out);
            }
            i = start + digits;
            last = i;
        }
        out.push_str(&input[last..]);
    }
}

/// `\bHEX{8}-HEX{4}-HEX{4}-HEX{4}-HEX{12}\b`
pub struct Uuids {
    pub number: Paint,
    pub letter: Paint,
    pub separator: Paint,
}

impl Highlighter for Uuids {
    fn apply(&self, input: &str, out: &mut String) {
        const GROUPS: [usize; 5] = [8, 4, 4, 4, 12];
        let s = input.as_bytes();
        let mut i = 0usize;
        let mut last = 0usize;
        'outer: while i < s.len() {
            if !is_hex(s[i]) || !left_free(s, i) {
                i += 1;
                continue;
            }
            let mut p = i;
            for (gi, &len) in GROUPS.iter().enumerate() {
                if p + len > s.len() || !s[p..p + len].iter().all(|&c| is_hex(c)) {
                    i += 1;
                    continue 'outer;
                }
                p += len;
                if gi < 4 {
                    if p >= s.len() || s[p] != b'-' {
                        i += 1;
                        continue 'outer;
                    }
                    p += 1;
                }
            }
            if !right_free(s, p) {
                i += 1;
                continue;
            }
            out.push_str(&input[last..i]);
            for &c in &s[i..p] {
                if c == b'-' {
                    self.separator.wrap_char('-', out);
                } else if c.is_ascii_digit() {
                    self.number.wrap_char(c as char, out);
                } else {
                    self.letter.wrap_char(c as char, out);
                }
            }
            i = p;
            last = p;
        }
        out.push_str(&input[last..]);
    }
}

