use crate::engine::Highlighter;
use crate::scan::*;
use crate::style::Paint;

fn dd(s: &[u8], i: usize) -> bool {
    if i + 1 >= s.len() {
        return false;
    }
    let (a, b) = (s[i], s[i + 1]);
    if !a.is_ascii_digit() || !b.is_ascii_digit() {
        return false;
    }
    match a {
        b'0' => b != b'0',
        b'1' | b'2' => true,
        b'3' => b == b'0' || b == b'1',
        _ => false,
    }
}

fn year(s: &[u8], i: usize) -> bool {
    i + 3 < s.len()
        && (&s[i..i + 2] == b"19" || &s[i..i + 2] == b"20")
        && s[i + 2].is_ascii_digit()
        && s[i + 3].is_ascii_digit()
}

fn sep(b: u8) -> bool {
    b == b'-' || b == b'/'
}

/// Calendar dates, either `YYYY<s>DD<s>DD` or `DD<s>DD<s>YYYY`. Both render in
/// year-first order, so the second form is reordered on output.
pub struct Dates {
    pub number: Paint,
    pub separator: Paint,
}

impl Highlighter for Dates {
    fn apply(&self, input: &str, out: &mut String) {
        let s = input.as_bytes();
        let mut i = 0usize;
        let mut last = 0usize;
        while i < s.len() {
            // year-first
            if year(s, i) && sep(s[i + 4]) && dd(s, i + 5) && i + 7 < s.len() && sep(s[i + 7]) && dd(s, i + 8) {
                out.push_str(&input[last..i]);
                self.emit(&input[i..i + 4], s[i + 4], &input[i + 5..i + 7], s[i + 7], &input[i + 8..i + 10], out);
                i += 10;
                last = i;
                continue;
            }
            // day-first, rendered year-first
            if dd(s, i)
                && i + 2 < s.len()
                && sep(s[i + 2])
                && dd(s, i + 3)
                && i + 5 < s.len()
                && sep(s[i + 5])
                && year(s, i + 6)
            {
                out.push_str(&input[last..i]);
                self.emit(&input[i + 6..i + 10], s[i + 2], &input[i..i + 2], s[i + 5], &input[i + 3..i + 5], out);
                i += 10;
                last = i;
                continue;
            }
            i += 1;
        }
        out.push_str(&input[last..]);
    }
