    fn emit(&self, y: &str, s1: u8, a: &str, s2: u8, b: &str, out: &mut String) {
        self.number.wrap(y, out);
        self.separator.wrap_char(s1 as char, out);
        self.number.wrap(a, out);
        self.separator.wrap_char(s2 as char, out);
        self.number.wrap(b, out);
