fn hour_len(s: &[u8], i: usize) -> Option<usize> {
    if i >= s.len() || !s[i].is_ascii_digit() {
        return None;
    }
    let two = i + 1 < s.len() && s[i + 1].is_ascii_digit();
    if two {
        let (a, b) = (s[i], s[i + 1]);
