/// `"[^"]*"`, but a chunk holding an odd number of quotes is left alone entirely.
pub struct Quotes {
    pub style: Paint,
    pub quote: u8,
}

impl Highlighter for Quotes {
    fn apply(&self, input: &str, out: &mut String) {
        let s = input.as_bytes();
        let count = s.iter().filter(|&&c| c == self.quote).count();
        if count == 0 || count % 2 == 1 {
            out.push_str(input);
            return;
        }
        let mut i = 0usize;
        let mut last = 0usize;
        while i < s.len() {
            if s[i] != self.quote {
