                continue;
            }
            let mut j = i + 1;
            while s[j] != self.quote {
                j += 1;
            }
            out.push_str(&input[last..i]);
            self.style.wrap(&input[i..=j], out);
            i = j + 1;
            last = i;
        }
        out.push_str(&input[last..]);
    }
}

